// Code node — mode: Run Once for All Items

// query params that are noise, never identity
const TRACKING = [
  /^utm_/i, /^ga_/i, /^mc_/i, /^pk_/i, /^hsa_/i, /^_hs/i, /^__/,
  /^(ref|referrer|referer|source|src|medium|campaign)$/i,
  /^(fbclid|gclid|gbraid|wbraid|msclkid|ttclid|twclid|igshid|yclid|epik|li_fat_id)$/i,
  /^(trk|trkinfo|refid|trackingid|lipi|licu|originaltrk)$/i,
  /^(share|shared|si|feature|spm|scm|from|via|sessionid)$/i,
];

function hash16(str) {
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193);
    h2 = Math.imul(h2 ^ c, 0x85ebca6b);
  }
  return (h1 >>> 0).toString(16).padStart(8, '0')
       + (h2 >>> 0).toString(16).padStart(8, '0');
}

function clean(input) {
  let s = String(input || '').trim();
  s = s.replace(/^<|>$/g, '').split('|')[0].trim();  // Slack <url|label>
  return s.split('#')[0];                             // drop fragment
}

function canonicalize(url) {
  const m = url.match(/^(?:https?:\/\/)?([^\/?#:]+)(?::\d+)?([^?]*)(?:\?(.*))?$/i);
  if (!m) return { host: '', canonical: url.toLowerCase() };

  const host = m[1].replace(/^(www\d?|m|mobile)\./i, '').toLowerCase();
  const path = (m[2] || '').replace(/\/{2,}/g, '/').replace(/\/+$/, '');

  const query = (m[3] || '')
    .split('&')
    .filter(Boolean)
    .map(p => {
      const i = p.indexOf('=');
      return i === -1 ? [p, ''] : [p.slice(0, i), p.slice(i + 1)];
    })
    .filter(([k]) => k && !TRACKING.some(re => re.test(k)))
    .sort((a, b) => a[0].localeCompare(b[0]))   // param order must not matter
    .map(([k, v]) => `${k}=${v}`)
    .join('&');

  return { host, canonical: host + path + (query ? '?' + query : '') };
}

return $input.all().map(item => {
  const data = item.json.output ?? item.json;
  const raw = clean(data['Job URL'] ?? data.job_url ?? '');
  const { host, canonical } = canonicalize(raw);

  return {
    json: {
      job_url: raw,
      url_source: host || 'unknown',
      job_id: hash16(canonical),
    }
  };
});

